    add(obj, o) { const i = nn++; aK.setXYZW(i, o.hb, o.len, o.oars || 0, o.way); aB.setXYZ(i, 0, o.hw, 0); held.push(obj); return i; },
    // k: the curvature of her way here; run: the metres she has made along her round
    bend(i, k, run = 0) { aB.setX(i, k); aB.setZ(i, run % 1150); },
    place() { for (let i = 0; i < held.length; i++) { held[i].updateMatrix(); mesh.setMatrixAt(i, held[i].matrix); } mesh.instanceMatrix.needsUpdate = true; aB.needsUpdate = true; },
