// a round's curvature at s (the change of heading to a metre of way; the heading eases round each corner)
function bendAt(round, s) { const a = round.at(s)[2], b = round.at(s - 4 / round.length)[2]; let d = a - b; while (d > Math.PI) d -= 2 * Math.PI; while (d < -Math.PI) d += 2 * Math.PI; return d / 4; }
